def fitK(K, tp=range(0,4), ap=range(-1,3)):
    cols=[]
    base=A/(K+A)
    for i in tp:
        cols.append(t**i*base)
    for i in range(0,4):
        for j in ap:
            cols.append(t**i*A**j)
    X=np.array(cols).T
    c=np.linalg.lstsq(X,dA_dt,rcond=None)[0]
    return np.mean((X@c-dA_dt)**2)/np.var(dA_dt), c
